import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { changeAccountHandler } from "../handlers/changeAccountHandler";
import type { ApiError } from "../runtime/client";
import type { ChangeAccountRequest } from "../types/ChangeAccountRequest";

type Data = Awaited<ReturnType<typeof changeAccountHandler>>;
type Vars = ChangeAccountRequest;

export function useChangeAccount(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => changeAccountHandler(vars),
    ...options,
  });
}
